// `./brand` is generated by `yarn fonts:sync` (runs on postinstall). It holds
// the licensed brand typeface for official builds, or open-source Inter when
// the private font source is unavailable. See docs/private-font-split-design.md.
import { brandFontManifest } from './brand/manifest';

// Native fontFamily names. iOS resolves them by PostScript name and Android by
// assets/fonts/<name>.ttf, so they follow whichever typeface is installed.
export const BRAND_FONT_NATIVE_FAMILY = brandFontManifest.nativeFamily;

// Web @font-face alias declared in web-fonts.css; independent of the typeface.
export const BRAND_FONT_WEB_FAMILY = 'OneKeySans';

export const BRAND_FONT_SOURCE = brandFontManifest.source;
